import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DpI_zlPE.js";var i=JSON.parse(`{"title":"食","description":"","frontmatter":{},"headers":[],"relativePath":"ccc/生活/食.md","filePath":"ccc/生活/食.md"}`),a={name:`ccc/生活/食.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="食" tabindex="-1">食 <a class="header-anchor" href="#食" aria-label="Permalink to “食”">​</a></h1><h2 id="酒" tabindex="-1">酒 <a class="header-anchor" href="#酒" aria-label="Permalink to “酒”">​</a></h2><p><strong>酒精是一级致癌物</strong></p><p>红酒可以考虑奥乐齐贴牌、采购分装，几个便宜的对得起价格。盒马外卖牌子货，智利干露、奥兰小红帽、奔富红酒，性价比差点。友商外卖，凯樽汇锦殿白诗南，摩泽尔雷司令，外卖价格不美丽。</p><p>京东自营前置秒送仓，在京东秒送下单，价格在秒送商超里相对实惠一点。</p><p>果味啤酒，黑狮玫瑰红覆盆子果啤。</p><p>阿彭策尔小麦拉格；施耐德IPA；智美红蓝帽；鹅岛IPA，京A（嘉士伯代工，可以当成中国鹅岛）。</p><p>盒马外卖，盒马贴牌鲜摘酒花，京A-酒花漫步，纸飞机飞个啤。</p><p>奥乐齐、盒马、京东贴牌，代工方，斑马精酿、杭州千岛湖，水平还可以。久燚臻水平不俗，但是这些商超嫌贵不贴牌。。。</p><p>青岛松江工厂，在部分商超铺货所谓生啤鲜啤，9.9一罐1L还可以考虑，至少清冽，再贵对不起价格。</p><p>工业拉格，口感清冽反而存在难度，酒的发酵如果有缺陷，所谓精酿就可以东加西加，把味盖住，这也是为什么国产所谓精酿小厂雨后春笋一般冒出来，往往这些厂大概率是没有做好工业拉格的水平。</p><p>找不到贴牌千岛湖，青岛小金棕，玻璃瓶装330ml，看麦芽度酒精度数字比大小不怎么样，但水平还可以，没有杂味，带点麦香的水啤。更贵价，喜力、麒麟、朝日，除了性价比低点，水平在线。</p><p>白熊、福佳白、1664等比利时小麦，增味型的香气实质都是香精。如果完全靠投放陈皮、香菜籽，要达到其成品的香气，不易萃取，且成本太高，生产工艺上也比较麻烦。所以国产比利时小麦感觉香气很淡的，反而可能真的是靠投放陈皮香菜籽。</p><p>老骚友推荐，老骚友拒绝香料增味，独爱酒花，相对而言都是烈马。</p><blockquote><p>不一定上来就干烈马，麒麟一番榨季节限定，施耐德5号，鹅岛IPA，京A，国产的如大九酿造、美西、黄河水，先试试水看看能不能接受酒花味。</p></blockquote><p>经典拉格：喜力、青岛。倭国的朝日、麒麟等还凑合。百威整体感觉很拉跨，雪花、嘉士伯收购的要看情况。</p><p>捷克皮尔森拉格、淡色拉格：乌奎尔</p><p>德式小麦：施耐德</p><p>兰比克啤酒（比利时）：Fruli芙力，</p><p>修道院啤酒：智美蓝帽（双料）粉象（双料三料）</p><p>经典IPA：内华达山脉</p><p>浑浊IPA：击倒巨人，僧侣（贵）</p><p><strong>小众地方性传统酒</strong></p><p>西安七立稠酒 黑米黄酒 浙一家 米酒 醉金花 贵州醪糟</p><h2 id="咖啡" tabindex="-1">咖啡 <a class="header-anchor" href="#咖啡" aria-label="Permalink to “咖啡”">​</a></h2><p>用咖啡豆太麻烦了，我一般就是买瑞幸冻干咖啡粉，微酸，反正就那味呗，着重功能性。</p><p>云南省农业农村厅“2022年云南省精品咖啡庄园”：</p><p>天宇咖啡庄园 来珠克咖啡庄园 比顿咖啡庄园 佐园咖啡庄园 新寨咖啡庄园，电商同名。 高晟咖啡庄园 益嘉园咖啡庄园 粒述咖啡庄园 荣康达咖啡庄园</p><h2 id="杂" tabindex="-1">杂 <a class="header-anchor" href="#杂" aria-label="Permalink to “杂”">​</a></h2><p>味之素、鼎味泰，关东煮汤料</p>`,30)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};